import argparse
import json
import os
import subprocess
import xml.etree.ElementTree as ET

def parse_args():
    parser = argparse.ArgumentParser(description='Run jobs from XML and cache results in JSON.')
    parser.add_argument('jobs_xml', type=str, help='Path to the XML file containing jobs')
    parser.add_argument('results_json', type=str, help='Path to the JSON cache file')
    return parser.parse_args()

def load_cache(cache_path):
    if os.path.exists(cache_path):
        with open(cache_path, 'r') as f:
            return json.load(f)
    return {}

def save_cache(cache_path, cache_data):
    with open(cache_path, 'w') as f:
        json.dump(cache_data, f, indent=2)

def parse_jobs(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.get('id'),
            'command': job_elem.find('command').text
        }
        jobs.append(job)
    return jobs

def run_job(job_id, command):
    result = subprocess.run(command, shell=True, capture_output=True, text=True)
    return {
        'stdout': result.stdout,
        'exit_code': result.returncode
    }

def main():
    args = parse_args()
    jobs_xml = args.jobs_xml
    results_json = args.results_json

    cache = load_cache(results_json)
    jobs = parse_jobs(jobs_xml)

    for job in jobs:
        if job['id'] not in cache:
            stdout, exit_code = run_job(job['id'], job['command'])
            cache[job['id']] = {
                'stdout': stdout,
                'exit_code': exit_code
            }
            print(f"{job['id']} {exit_code}")

    save_cache(results_json, cache)

if __name__ == "__main__":
    main()

import sys
import json
import xml.etree.ElementTree as ET
import subprocess

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.get('id'),
            'command': job_elem.find('command').text
        }
        jobs.append(job)
    return jobs

def load_cache(cache_file):
    try:
        with open(cache_file, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def save_cache(cache_file, cache_data):
    with open(cache_file, 'w') as f:
        json.dump(cache_data, f, indent=2)

def run_jobs(jobs, cache):
    executed = []
    for job in jobs:
        job_id = job['id']
        if job_id not in cache:
            try:
                result = subprocess.run(
                    job['command'],
                    shell=True,
                    check=True,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.PIPE,
                    text=True
                )
                cache[job_id] = {
                    'stdout': result.stdout,
                    'exit_code': result.returncode
                }
                executed.append((job_id, result.returncode))
            except subprocess.CalledProcessError as e:
                cache[job_id] = {
                    'stdout': e.stderr,
                    'exit_code': e.returncode
                }
                executed.append((job_id, e.returncode))
    return executed

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python run_jobs.py <jobs.xml> <results.json>")
        sys.exit(1)

    xml_file = sys.argv[1]
    cache_file = sys.argv[2]

    jobs = parse_xml(xml_file)
    cache = load_cache(cache_file)

    executed_jobs = run_jobs(jobs, cache)

    for job_id, exit_code in executed_jobs:
        print(f"{job_id} {exit_code}")

    save_cache(cache_file, cache)

import argparse
import json
import subprocess
import xml.etree.ElementTree as ET
from pathlib import Path

def parse_xml(xml_file):
    tree = ET.parse(xml_file)
    root = tree.getroot()
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.get('id'),
            'command': job_elem.find('command').text
        }
        jobs.append(job)
    return jobs

def process_jobs(jobs, cache_file):
    cache = {}
    if Path(cache_file).exists():
        with open(cache_file, 'r') as f:
            cache = json.load(f)

    executed_jobs = []
    for job in jobs:
        job_id = job['id']
        if job_id not in cache:
            result = subprocess.run(job['command'], shell=True, capture_output=True, text=True)
            cache[job_id] = {
                'stdout': result.stdout,
                'exit_code': result.returncode
            }
            executed_jobs.append((job_id, result.returncode))

    with open(cache_file, 'w') as f:
        json.dump(cache, f, indent=2)

    for job_id, exit_code in executed_jobs:
        print(f"{job_id} {exit_code}")

def main():
    parser = argparse.ArgumentParser(description='Run jobs from XML and cache results in JSON.')
    parser.add_argument('xml_file', help='XML file containing jobs')
    parser.add_argument('json_file', help='JSON file to cache results')
    args = parser.parse_args()

    jobs = parse_xml(args.xml_file)
    process_jobs(jobs, args.json_file)

if __name__ == '__main__':
    main()
